    @Override
    public List<Payment> findByUserEmailAndCategory(String email, PaymentCategory category) {
        return queryFactory
                .selectFrom(notification)
                .join(notification.user, user).fetchJoin()
                .where(
                        userEmailEq(email),
                        categoryEq(category)
                )
                .orderBy(notification.createdDate.desc())
                .fetch();
    }

    @Override
    public List<Payment> findByUserEmailAndType(String email, PaymentType type) {
        return queryFactory
                .selectFrom(notification)
                .join(notification.user, user).fetchJoin()
                .where(
                        userEmailEq(email),
                        typeEq(type)
                )
                .orderBy(notification.createdDate.desc())
                .fetch();
    }

    @Override
    public Page<Payment> findByUserEmailAndIsRead(String email, boolean isRead, Pageable pageable) {
        List<Payment> content = queryFactory
                .selectFrom(notification)
                .join(notification.user, user).fetchJoin()
                .where(
                        userEmailEq(email),
                        isReadEq(isRead)
                )
                .orderBy(getOrderSpecifiers(pageable).toArray(OrderSpecifier[]::new))
                .offset(pageable.getOffset())
                .limit(pageable.getPageSize())
                .fetch();

        JPAQuery<Long> countQuery = queryFactory
                .select(notification.count())
                .from(notification)
                .join(notification.user, user)
                .where(
                        userEmailEq(email),
                        isReadEq(isRead)
                );

        return PageableExecutionUtils.getPage(content, pageable, countQuery::fetchOne);
    }

